package clip

import (
	"net/url"
	"slices"
	"strings"
)

// Pure helpers of the macOS pasteboard code (clip_darwin.go), kept free of
// build tags so that they are tested on every platform.

// Pasteboard types (UTIs).
const (
	typeText    = "public.utf8-plain-text"
	typePNG     = "public.png"
	typeTIFF    = "public.tiff"
	typeFileURL = "public.file-url"
	// The nspasteboard.org markers: content clipboard managers should not
	// record (passwords), content that is only on the clipboard briefly,
	// and content generated by a program rather than copied by the user.
	typeConcealed     = "org.nspasteboard.ConcealedType"
	typeTransient     = "org.nspasteboard.TransientType"
	typeAutoGenerated = "org.nspasteboard.AutoGeneratedType"
)

// excludedTypes reports whether pasteboard content with the types asks
// clipboard managers not to record it: it is marked concealed (passwords),
// transient or auto-generated (nspasteboard.org).
func excludedTypes(types []string) bool {
	return slices.ContainsFunc(types, func(t string) bool {
		switch t {
		case "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
			// Older names some password managers still write.
			"com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType":
			return true
		}
		return false
	})
}

// pbData is one type of a pasteboard item: its UTI and data.
type pbData struct {
	typ  string
	data []byte
}

// contains reports whether types has t.
func contains(types []string, t string) bool { return slices.Contains(types, t) }

// fileURLPath returns the local path of a file URL ("file:///Users/a/b%20c"
// or "file://localhost/..."), without a trailing slash for folders; ok is
// false for anything else.
func fileURLPath(s string) (string, bool) {
	u, err := url.Parse(s)
	if err != nil || u.Scheme != "file" || (u.Host != "" && u.Host != "localhost") || u.Path == "" {
		return "", false
	}
	p := u.Path
	if len(p) > 1 {
		p = strings.TrimSuffix(p, "/")
	}
	return p, true
}

// probeTypes is HasFilesOrImage for pasteboard content with the types:
// file URLs, or an image and no text, unless the content is excluded. With
// an image and text, askText is set: the text decides (DescribesImage).
func probeTypes(types []string) (ok, askText bool) {
	switch {
	case excludedTypes(types):
		return false, false
	case contains(types, typeFileURL):
		return true, false
	case !contains(types, typePNG) && !contains(types, typeTIFF):
		return false, false
	case contains(types, typeText):
		return false, true
	}
	return true, false
}

// blank reports whether s is empty or only white space.
func blank(s string) bool { return strings.TrimSpace(s) == "" }
